def build_deep_mlp(dim, depth, init_fn):
    layers = []
    for _ in range(depth):
        linear = nn.Linear(dim, dim)
        init_fn(linear.weight)
        nn.init.zeros_(linear.bias)
        layers += [linear, nn.ReLU()]
    return nn.Sequential(*layers)


