import torch.nn as nn

class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self.pretrained_backbone = nn.Sequential(nn.Linear(100, 64), nn.ReLU(), nn.Linear(64, 32))
        self.new_head = nn.Linear(32, 10)

    def forward(self, x):
        return self.new_head(self.pretrained_backbone(x))


def build_optimizer(model, backbone_lr=1e-5, head_lr=1e-3, weight_decay=0.01):
    param_groups = [
        {'params': model.pretrained_backbone.parameters(), 'lr': backbone_lr},
        {'params': model.new_head.parameters(), 'lr': head_lr},
    ]
    return torch.optim.AdamW(param_groups, weight_decay=weight_decay)


