import torch
import torch.nn as nn
import torch.nn.functional as F

class ContrastiveLoss(nn.Module):
    def __init__(self, margin=1.0):
        super().__init__()
        self.margin = margin

    def forward(self, emb1, emb2, label):
        # label: 1 if same class/pair, 0 if different
        d = F.pairwise_distance(emb1, emb2, p=2)
        loss = label * d.pow(2) + (1 - label) * F.relu(self.margin - d).pow(2)
        return loss.mean()


class SiameseNetwork(nn.Module):
    def __init__(self, in_dim=784, embed_dim=32):
        super().__init__()
        self.encoder = nn.Sequential(
            nn.Linear(in_dim, 128), nn.ReLU(),
            nn.Linear(128, embed_dim)
        )

    def forward(self, x1, x2):
        return self.encoder(x1), self.encoder(x2)


if __name__ == '__main__':
    torch.manual_seed(0)
    model = SiameseNetwork()
    criterion = ContrastiveLoss(margin=1.0)
    optimizer = torch.optim.Adam(model.parameters(), lr=1e-3)

    x1 = torch.randn(8, 784)
    x2 = torch.randn(8, 784)
    labels = torch.randint(0, 2, (8,)).float()

    for step in range(3):
        emb1, emb2 = model(x1, x2)
        loss = criterion(emb1, emb2, labels)
        optimizer.zero_grad()
        loss.backward()
        optimizer.step()
        print(f'step {step}, loss {loss.item():.4f}')

