from torch.utils.data import Sampler, DataLoader, Dataset

class StatefulSampler(Sampler):
    """A sampler that can save/restore its position mid-epoch."""
    def __init__(self, data_source, seed=0):
        self.data_source = data_source
        self.seed = seed
        self.epoch = 0
        self.start_index = 0  # index within the current epoch's shuffled order
        self._order = None

    def set_epoch(self, epoch):
        self.epoch = epoch
        self.start_index = 0
        self._order = None  # force regeneration with new epoch's seed

    def _generate_order(self):
        g = torch.Generator()
        g.manual_seed(self.seed + self.epoch)
        return torch.randperm(len(self.data_source), generator=g).tolist()

    def __iter__(self):
        if self._order is None:
            self._order = self._generate_order()
        # Resume from start_index instead of 0
        for idx in range(self.start_index, len(self._order)):
            self.start_index = idx + 1  # track progress as we go
            yield self._order[idx]

    def __len__(self):
        return len(self.data_source) - self.start_index

    def state_dict(self):
        return {"epoch": self.epoch, "start_index": self.start_index, "order": self._order}

    def load_state_dict(self, state):
        self.epoch = state["epoch"]
        self.start_index = state["start_index"]
        self._order = state["order"]


def save_checkpoint(path, model, optimizer, sampler, epoch):
    torch.save({
        "model_state": model.state_dict(),
        "optimizer_state": optimizer.state_dict(),
        "sampler_state": sampler.state_dict(),
