import torch

class Callback:
    """Base class -- override only the hooks you need."""
    def on_epoch_end(self, epoch, logs): pass
    def on_batch_end(self, batch, logs): pass
    def on_validation_end(self, epoch, logs): pass


class LRLoggerCallback(Callback):
    def __init__(self, optimizer):
        self.optimizer = optimizer

    def on_epoch_end(self, epoch, logs):
        lr = self.optimizer.param_groups[0]["lr"]
        print(f"[LR Logger] Epoch {epoch}: lr = {lr:.6f}")


class EarlyStoppingCallback(Callback):
    def __init__(self, patience=5):
        self.patience = patience
        self.best_loss = float("inf")
        self.wait = 0
        self.should_stop = False

    def on_validation_end(self, epoch, logs):
        val_loss = logs["val_loss"]
        if val_loss < self.best_loss:
            self.best_loss = val_loss
            self.wait = 0
        else:
            self.wait += 1
            if self.wait >= self.patience:
                self.should_stop = True
                print(f"[EarlyStopping] No improvement for {self.patience} epochs. Stopping.")


class CheckpointCallback(Callback):
    def __init__(self, model, path="best_model.pt"):
        self.model = model
        self.path = path
        self.best_loss = float("inf")

    def on_validation_end(self, epoch, logs):
        if logs["val_loss"] < self.best_loss:
            self.best_loss = logs["val_loss"]
            torch.save(self.model.state_dict(), self.path)
            print(f"[Checkpoint] Saved new best model at epoch {epoch}")


def train_with_callbacks(model, optimizer, train_loader, val_loader, epochs, callbacks):
    for epoch in range(epochs):
        model.train()
        for batch_idx, (x, y) in enumerate(train_loader):
            optimizer.zero_grad()
            loss = torch.nn.functional.cross_entropy(model(x), y)
            loss.backward()
            optimizer.step()
            for cb in callbacks:
                cb.on_batch_end(batch_idx, {"loss": loss.item()})

        model.eval()
        val_loss = 0.0
        with torch.no_grad():
            for x, y in val_loader:
                val_loss += torch.nn.functional.cross_entropy(model(x), y).item()
        val_loss /= len(val_loader)

        for cb in callbacks:
            cb.on_validation_end(epoch, {"val_loss": val_loss})
            cb.on_epoch_end(epoch, {"val_loss": val_loss})

        if any(getattr(cb, "should_stop", False) for cb in callbacks):
            print("Stopping training early.")
            break


