class EMA:
    def __init__(self, model, decay=0.999):
        self.decay = decay
        self.shadow = copy.deepcopy(model)  # a separate, frozen copy of the model
        for p in self.shadow.parameters():
            p.requires_grad = False

    @torch.no_grad()
    def update(self, model):
        for shadow_p, model_p in zip(self.shadow.parameters(), model.parameters()):
            shadow_p.data.mul_(self.decay).add_(model_p.data, alpha=1 - self.decay)
        # Also sync buffers (e.g. BatchNorm running stats) directly, no averaging needed
        for shadow_b, model_b in zip(self.shadow.buffers(), model.buffers()):
            shadow_b.data.copy_(model_b.data)

    def state_dict(self):
        return self.shadow.state_dict()


