from collections import Counter, defaultdict

class SimpleBPE:
    def __init__(self, vocab_size=300):
        self.vocab_size = vocab_size
        self.merges = {}   # (tokenA, tokenB) -> merged_token, in learned order

    def _get_stats(self, corpus_words):
        pairs = Counter()
        for word, freq in corpus_words.items():
            symbols = word
            for i in range(len(symbols) - 1):
                pairs[(symbols[i], symbols[i + 1])] += freq
        return pairs

    def _merge_word(self, word, pair, new_symbol):
        merged = []
        i = 0
        while i < len(word):
            if i < len(word) - 1 and word[i] == pair[0] and word[i + 1] == pair[1]:
                merged.append(new_symbol)
                i += 2
            else:
                merged.append(word[i])
                i += 1
        return tuple(merged)

    def fit(self, corpus):
        # represent every word as a tuple of characters, plus an end-of-word marker
        words = Counter(w + "_" for w in corpus.split())
        corpus_words = {tuple(w): f for w, f in words.items()}

        while True:
            vocab = set(sym for w in corpus_words for sym in w)
            if len(vocab) >= self.vocab_size:
                break
            pairs = self._get_stats(corpus_words)
            if not pairs:
                break
            best_pair = max(pairs, key=pairs.get)
            new_symbol = best_pair[0] + best_pair[1]
            self.merges[best_pair] = new_symbol
            corpus_words = {
                self._merge_word(w, best_pair, new_symbol): f
                for w, f in corpus_words.items()
            }
        self.vocab = sorted(vocab)
        self.token_to_id = {t: i for i, t in enumerate(self.vocab)}
        self.id_to_token = {i: t for t, i in self.token_to_id.items()}

    def encode(self, word):
        symbols = list(word + "_")
        for pair, merged in self.merges.items():
            i = 0
            new_symbols = []
            while i < len(symbols):
                if i < len(symbols) - 1 and symbols[i] == pair[0] and symbols[i + 1] == pair[1]:
                    new_symbols.append(merged)
                    i += 2
                else:
                    new_symbols.append(symbols[i])
                    i += 1
            symbols = new_symbols
        return [self.token_to_id[s] for s in symbols if s in self.token_to_id]

    def decode(self, ids):
        return "".join(self.id_to_token[i] for i in ids).replace("_", " ").strip()


