import torch
import torch.nn as nn
import torch.nn.functional as F

class EWC:
    def __init__(self, model, general_dataloader, device, n_batches=20):
        self.model = model
        self.device = device
        self.params_old = {n: p.clone().detach() for n, p in model.named_parameters() if p.requires_grad}
        self.fisher = self._compute_fisher(general_dataloader, n_batches)

    def _compute_fisher(self, dataloader, n_batches):
        fisher = {n: torch.zeros_like(p) for n, p in self.model.named_parameters() if p.requires_grad}
        self.model.eval()
        for i, batch in enumerate(dataloader):
            if i >= n_batches:
                break
            input_ids = batch["input_ids"].to(self.device)
            labels = batch["labels"].to(self.device)
            self.model.zero_grad()
            logits = self.model(input_ids).logits
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), labels.view(-1))
            loss.backward()
            for n, p in self.model.named_parameters():
                if p.requires_grad and p.grad is not None:
                    fisher[n] += p.grad.detach() ** 2 / n_batches
        return fisher

    def penalty(self):
        loss = 0.0
        for n, p in self.model.named_parameters():
            if p.requires_grad and n in self.fisher:
                loss += (self.fisher[n] * (p - self.params_old[n]) ** 2).sum()
        return loss


def continual_pretrain(model, domain_loader, general_loader, ewc, device,
                        steps=1000, base_lr=5e-5, warmup_steps=100, ewc_lambda=1000.0,
                        general_mix_ratio=0.3):
    optimizer = torch.optim.AdamW(model.parameters(), lr=base_lr)
    general_iter = iter(general_loader)

    def lr_at(step):
        if step < warmup_steps:
            return base_lr * step / warmup_steps
        return base_lr

    model.train()
    for step, domain_batch in enumerate(domain_loader):
        if step >= steps:
            break
        for g in optimizer.param_groups:
            g["lr"] = lr_at(step)

        # data mixing: occasionally train on general data instead of domain data
        if torch.rand(1).item() < general_mix_ratio:
            try:
                batch = next(general_iter)
            except StopIteration:
                general_iter = iter(general_loader)
                batch = next(general_iter)
        else:
            batch = domain_batch

        input_ids = batch["input_ids"].to(device)
        labels = batch["labels"].to(device)
        logits = model(input_ids).logits
        task_loss = F.cross_entropy(logits.view(-1, logits.size(-1)), labels.view(-1))
        loss = task_loss + ewc_lambda * ewc.penalty()

        optimizer.zero_grad()
        loss.backward()
        optimizer.step()

        if step % 100 == 0:
            print(f"step {step} loss {loss.item():.4f} task_loss {task_loss.item():.4f}")

