from collections import Counter

class ByteLevelBPE:
    def __init__(self, vocab_size=300):
        self.vocab_size = vocab_size
        self.merges = {}

    def _get_stats(self, seqs):
        pairs = Counter()
        for seq, freq in seqs.items():
            for i in range(len(seq) - 1):
                pairs[(seq[i], seq[i + 1])] += freq
        return pairs

    def _merge(self, seq, pair, new_id):
        merged = []
        i = 0
        while i < len(seq):
            if i < len(seq) - 1 and seq[i] == pair[0] and seq[i + 1] == pair[1]:
                merged.append(new_id)
                i += 2
            else:
                merged.append(seq[i])
                i += 1
        return tuple(merged)

    def fit(self, corpus: str):
        raw_bytes = corpus.encode("utf-8")
        word_freqs = Counter([tuple(raw_bytes)])  # treat whole corpus as one byte sequence for simplicity
        next_id = 256  # ids 0-255 are reserved for raw bytes

        seqs = word_freqs
        while len(set(b for seq in seqs for b in seq)) < self.vocab_size:
            pairs = self._get_stats(seqs)
            if not pairs:
                break
            best_pair = max(pairs, key=pairs.get)
            self.merges[best_pair] = next_id
            seqs = {self._merge(seq, best_pair, next_id): f for seq, f in seqs.items()}
            next_id += 1

    def encode(self, text: str):
        tokens = list(text.encode("utf-8"))  # start as raw byte ids (0-255)
        for pair, new_id in self.merges.items():
            merged = []
            i = 0
            while i < len(tokens):
                if i < len(tokens) - 1 and tokens[i] == pair[0] and tokens[i + 1] == pair[1]:
                    merged.append(new_id)
                    i += 2
                else:
                    merged.append(tokens[i])
                    i += 1
            tokens = merged
        return tokens

    def decode(self, ids):
        # reverse merges to expand back to raw bytes, then decode as UTF-8
        reverse_merges = {v: k for k, v in self.merges.items()}

        def expand(token_id):
            if token_id < 256:
                return [token_id]
            a, b = reverse_merges[token_id]
            return expand(a) + expand(b)

        byte_list = []
        for token_id in ids:
            byte_list.extend(expand(token_id))
        return bytes(byte_list).decode("utf-8", errors="replace")


