import torch
import torch.nn as nn
import torch.nn.functional as F

class Expert(nn.Module):
    def __init__(self, dim, hidden_dim):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(dim, hidden_dim), nn.GELU(), nn.Linear(hidden_dim, dim))

    def forward(self, x):
        return self.net(x)

class SparseMoE(nn.Module):
    def __init__(self, dim, hidden_dim, n_experts=8, top_k=2):
        super().__init__()
        self.top_k = top_k
        self.n_experts = n_experts
        self.experts = nn.ModuleList([Expert(dim, hidden_dim) for _ in range(n_experts)])
        self.router = nn.Linear(dim, n_experts)

    def forward(self, x):
        # x: (batch, seq, dim)
        B, T, C = x.shape
        x_flat = x.view(-1, C)  # (B*T, C)

        router_logits = self.router(x_flat)                     # (B*T, n_experts)
        topk_vals, topk_idx = torch.topk(router_logits, self.top_k, dim=-1)
        topk_weights = F.softmax(topk_vals, dim=-1)              # normalize only over the chosen experts

        output = torch.zeros_like(x_flat)
        for slot in range(self.top_k):
            expert_idx = topk_idx[:, slot]        # (B*T,) which expert each token picked in this slot
            weight = topk_weights[:, slot].unsqueeze(-1)  # (B*T, 1)
            for e in range(self.n_experts):
                token_mask = expert_idx == e
                if token_mask.any():
                    tokens = x_flat[token_mask]
                    expert_out = self.experts[e](tokens)
                    output[token_mask] += weight[token_mask] * expert_out

        return output.view(B, T, C)


if __name__ == "__main__":
    torch.manual_seed(0)
    moe = SparseMoE(dim=32, hidden_dim=64, n_experts=4, top_k=2)
    x = torch.randn(2, 5, 32)
    out = moe(x)
    print(out.shape)

import torch
import torch.nn as nn

class IA3ScaledLinear(nn.Module):
    """Wraps a frozen nn.Linear and multiplies its OUTPUT by a learned per-channel vector.
    Used for scaling key/value projections and FFN intermediate activations."""
    def __init__(self, base_linear: nn.Linear):
        super().__init__()
        self.base = base_linear
        for p in self.base.parameters():
            p.requires_grad = False
        out_features = base_linear.out_features
        self.ia3_vector = nn.Parameter(torch.ones(out_features))  # init at 1 -> no effect initially

    def forward(self, x):
        out = self.base(x)
        return out * self.ia3_vector  # element-wise rescaling of each output channel


def inject_ia3(model, target_names=("k_proj", "v_proj", "ffn_up")):
    for p in model.parameters():
        p.requires_grad = False
    for module in model.modules():
        for child_name, child in list(module.named_children()):
            if child_name in target_names and isinstance(child, nn.Linear):
                setattr(module, child_name, IA3ScaledLinear(child))
    return model


