import json
import re

tools = [
    {
        "name": "get_weather",
        "description": "Get the current weather for a city",
        "parameters": {"city": "string"},
    },
    {
        "name": "calculator",
        "description": "Evaluate a basic arithmetic expression",
        "parameters": {"expression": "string"},
    },
]

def build_system_prompt(tools):
    tool_descriptions = json.dumps(tools, indent=2)
    return (
        "You are an assistant with access to these tools:\n"
        f"{tool_descriptions}\n"
        "To call a tool, respond with EXACTLY this format and nothing else:\n"
        '<tool_call>{"name": "<tool_name>", "arguments": {...}}</tool_call>\n'
        "Otherwise, respond normally to the user."
    )

def parse_tool_call(model_output: str):
    match = re.search(r"<tool_call>(.*?)</tool_call>", model_output, re.DOTALL)
    if not match:
        return None
    return json.loads(match.group(1))

def execute_tool(call):
    name, args = call["name"], call["arguments"]
    if name == "get_weather":
        return f"The weather in {args['city']} is sunny, 22C."  # stub / mock implementation
    if name == "calculator":
        return str(eval(args["expression"], {"__builtins__": {}}))
    return f"Unknown tool: {name}"

def run_agent_turn(model_generate_fn, conversation):
    """model_generate_fn: a function(prompt: str) -> str representing one LLM call."""
    system_prompt = build_system_prompt(tools)
    prompt = system_prompt + "\n\n" + conversation

    model_output = model_generate_fn(prompt)
    call = parse_tool_call(model_output)

    if call is not None:
        tool_result = execute_tool(call)
        conversation += f"\nAssistant (tool call): {model_output}"
        conversation += f"\nTool result: {tool_result}"
        final_output = model_generate_fn(system_prompt + "\n\n" + conversation)
        return final_output

    return model_output

